<style>
.lf-ann-layer{position:fixed;inset:0;z-index:10000;background:#020617aa;display:flex;align-items:center;justify-content:center;padding:18px}.lf-ann{font:15px/1.6 system-ui;color:#10213d;background:linear-gradient(135deg,#f8fbff,#eeeaff);border:1px solid #8b9be8;border-radius:20px;box-shadow:0 20px 70px #0005;padding:25px;max-width:650px;width:100%;max-height:85dvh;overflow:auto;position:relative;box-sizing:border-box}.lf-ann{animation:lfAnnIn .25s ease-out}@keyframes lfAnnIn{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}.lf-ann h2{color:#24367d;margin:0 35px 8px 0}.lf-ann img{display:block;width:100%;max-height:45dvh;object-fit:contain;border-radius:13px;margin:12px 0}.lf-ann-close{position:sticky;float:right;top:0;border:0;border-radius:50%;background:#253477;color:white;width:34px;height:34px;font-size:23px;cursor:pointer;z-index:2}.lf-ann-cta{display:inline-block;background:linear-gradient(100deg,#245bcb,#7946ce);color:white!important;padding:10px 20px;border-radius:9px;text-decoration:none}.lf-ann-inline{margin:12px auto}.lf-ann-top,.lf-ann-bottom{position:fixed;left:0;right:0;max-width:none;border-radius:0;z-index:9997;max-height:35dvh}.lf-ann-top{top:0}.lf-ann-bottom{bottom:0}.lf-ann-corner{position:fixed;bottom:20px;right:20px;width:min(380px,calc(100vw - 40px));z-index:9997}.lf-ann-ticker .lf-ann-content{white-space:nowrap;animation:lfTicker 25s linear infinite}.lf-ann-ticker:hover .lf-ann-content,.lf-ann-ticker:focus-within .lf-ann-content{animation-play-state:paused}.lf-ann-ticker{overflow:hidden}.lf-ann-ticker img{display:none}@keyframes lfTicker{from{transform:translateX(100%)}to{transform:translateX(-100%)}}@media(prefers-reduced-motion:reduce){.lf-ann{animation:none}.lf-ann-ticker .lf-ann-content{animation:none;white-space:normal}}@media(prefers-color-scheme:dark){.lf-ann{background:linear-gradient(135deg,#101e3e,#261c48);color:#edf3ff}.lf-ann{animation:lfAnnIn .25s ease-out}@keyframes lfAnnIn{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}.lf-ann h2{color:#c7d8ff}}
</style>
<script>
(()=>{
const items={{ Illuminate\Support\Js::from($items) }}, csrf={{ Illuminate\Support\Js::from(csrf_token()) }};let modalOpen=false;const queue=[];
const send=async(a,event)=>{try{await fetch('/announcements/'+a.id+'/event',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({revision:a.revision,page:a.page,window:a.window,token:a.token,event}),keepalive:true});}catch(e){/* Analytics failure does not block navigation. */}};
const show=a=>{
 if(a.position==='center'&&modalOpen){queue.push(a);return;}const previous=document.activeElement;const root=document.createElement('div');root.className=a.position==='center'?'lf-ann-layer':'lf-ann lf-ann-'+a.position+(a.position==='banner'||a.position==='ticker'?' lf-ann-inline':'');
 const card=a.position==='center'?document.createElement('section'):root;if(a.position==='center'){modalOpen=true;card.className='lf-ann';card.setAttribute('role','dialog');card.setAttribute('aria-modal','true');root.append(card);}else{card.setAttribute('role','region');}
 card.setAttribute('aria-label',a.title);const close=document.createElement('button');close.className='lf-ann-close';close.type='button';close.textContent='×';close.setAttribute('aria-label','Close announcement');card.append(close);
 const dismiss=()=>{root.remove();if(a.position==='center'){modalOpen=false;previous?.focus();if(queue.length)show(queue.shift());}};close.onclick=dismiss;
 if(a.heading){const h=document.createElement('h2');h.textContent=a.heading;card.append(h);}if(a.subheading){const p=document.createElement('p');p.textContent=a.subheading;card.append(p);}
 if(a.image){const img=document.createElement('img');img.src=a.image;img.alt=a.image_alt||'';card.append(img);}const content=document.createElement('div');content.className='lf-ann-content';content.innerHTML=a.content||'';card.append(content);
 if(a.button_text&&a.button_url){const link=document.createElement('a');link.className='lf-ann-cta';link.href=a.button_url;link.textContent=a.button_text;link.rel='noopener noreferrer';link.addEventListener('click',()=>send(a,'click'));card.append(link);}
 root.addEventListener('keydown',e=>{if(e.key==='Escape')dismiss();if(a.position==='center'&&e.key==='Tab'){const controls=[...card.querySelectorAll('button,a[href]')];const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
 if(a.position==='banner'||a.position==='ticker'){document.body.prepend(root);}else{document.body.append(root);}if(a.position==='center')close.focus();const observer=new IntersectionObserver(entries=>{if(document.visibilityState==='visible'&&entries.some(e=>e.isIntersecting)){send(a,'view');observer.disconnect();}},{threshold:.1});observer.observe(card);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&card.isConnected){observer.unobserve(card);observer.observe(card);}});
};items.forEach(a=>setTimeout(()=>show(a),a.delay*1000));
})();
</script>
